<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$params=[];$where=$u['role']==='admin'?'1=1':'p.user_id=?';if($u['role']!=='admin')$params[]=$u['id'];if(!empty($_GET['available']))$where.=" AND p.status='available'";if(!empty($_GET['q'])){$where.=' AND (p.name LIKE ? OR p.unique_identifier LIKE ?)';$params[]='%'.$_GET['q'].'%';$params[]='%'.$_GET['q'].'%';}$s=db()->prepare("SELECT p.*,u.full_name owner_name,u.shop_name FROM products p JOIN users u ON u.id=p.user_id WHERE $where ORDER BY p.created_at DESC");$s->execute($params);$r=array_map('product_row',$s->fetchAll());out(['success'=>true,'products'=>$r]);
